const STATUS_FIELDS = {
  'approve': 'approved_at',
  'approved': 'approved_at',
  'to pay': 'to_pay_at',
  'topay': 'to_pay_at',
  'paid': 'paid_at',
  'for purchase': 'for_purchase_at',
  'purchase': 'for_purchase_at',
  'purchased': 'purchased_at',
};

function withStatusTimestamps(po) {
  const stamps = {
    approved_at: null,
    to_pay_at: null,
    paid_at: null,
    for_purchase_at: null,
    purchased_at: null,
  };

  for (const log of po.statusLogs || []) {
    const key = String(log.status || '').trim().toLowerCase();
    const field = STATUS_FIELDS[key];
    const ts = log.timestamp || null;
    if (!field || !ts) continue;
    // keep the earliest hit — some POs get approved twice
    if (!stamps[field] || ts < stamps[field]) stamps[field] = ts;
  }

  return { ...po, ...stamps };
}

return {
